; Move choice of the computer fighter
; $870c-$879a

; Gives a joystick value to each fighter that the computer controls. The value comes from the pose of the other fighter, the distance and a random column. It does nothing in a two-player game. It also does nothing when $af, $b2, $b4, $b5, $ba or $bb has bit 7 set. Demo ($b3 = 1): both fighters. One-player game: only fighter 1.
ai_choose_moves
        lda turn_request
        ora bout_loser
        ora walk_in_active
        ora setup_active
        ora time_out_active
        ora final_stage
        bmi ai_choose_done
        lda opponent_index              ; The opponent number selects one of 8 tables of 32 column numbers at $c8a2.
        asl
        tay
        lda ai_column_ptrs,y
        sta ai_level_ptr
        lda ai_column_ptrs+1,y
        sta ai_level_ptr+1
        ldx demo_mode                   ; X = the fighter that the computer looks at. The computer moves the other fighter.
        bne ai_choose_loop
        lda two_players
        bne ai_choose_done              ; Not taken in Part 2: the code writes only 0 to two_players.
ai_choose_loop
        stx cur_fighter
        lda fighter_pose,x              ; The pose of the watched fighter selects a pointer to a row list at $c9da.
        asl
        tay
        lda ai_row_ptrs,y
        sta move_ptr
        lda ai_row_ptrs+1,y
        sta move_ptr+1
        jsr get_fighter_distance
        ldx fighter_distance
        ldy distance_bands,x            ; Distance band 0-7 from $c9b2 selects a row number.
        lda (move_ptr),y
        jsr multiply_by_8               ; Row address = $cb38 + 8 * row number. A row holds 8 joystick values.
        adc #$38
        sta move_ptr
        lda move_ptr+1
        adc #$cb
        sta move_ptr+1
        lda #$f0                        ; Pointer to the 9 joystick directions at $cdf0 for the move look-up.
        sta direction_table_ptr
        lda #$cd
        sta direction_table_ptr+1
        lda cur_fighter                 ; X = the fighter that the computer moves.
        eor #$01
        tax
        inc ai_random                   ; The counter increments one time for each computer fighter in each pass of the main loop.
        lda demo_mode
        beq ai_choose_pick
        lda CIATBLO                     ; Demo only: the random number is CIA 1 timer B low EOR timer A low.
        eor CIATALO
        sta ai_random
ai_choose_pick
        lda ai_random                   ; Column 0-7 from the level table at a random position 0-31.
        and #$1f
        tay
        lda (ai_level_ptr),y
        tay
        lda (move_ptr),y                ; Uses the joystick value as input of the computer fighter.
        jsr joystick_to_direction
        jsr find_move_row
        jsr start_new_move
        ldx cur_fighter
        dex
        bpl ai_choose_loop
ai_choose_done
        rts
; Multiplies A by 8. Output: low byte in A, high byte in $88, carry clear for A < $20.
multiply_by_8
        pha
        lda #$00
        sta move_ptr+1
        pla
        asl
        rol move_ptr+1
        asl
        rol move_ptr+1
        asl
        rol move_ptr+1
        rts
